function mapReducer(f) {
  return (combine) => (acc, x) => combine(acc, f(x));
}

const double = (x) => x * 2;
const push = (acc, x) => { acc.push(x); return acc; };

const doubleThenPush = mapReducer(double)(push);

const result = [1, 2, 3].reduce(doubleThenPush, []);
console.log(result);

