function mapReducer(f) {
  return (combine) => (acc, x) => combine(acc, f(x));
}
function filterReducer(pred) {
  return (combine) => (acc, x) => (pred(x) ? combine(acc, x) : acc);
}
function compose2(f, g) {
  return (x) => f(g(x));
}

const push = (acc, x) => { acc.push(x); return acc; };
const isEven = (x) => x % 2 === 0;
const double = (x) => x * 2;

const transducer = compose2(filterReducer(isEven), mapReducer(double));
const combined = transducer(push);

const result = [1, 2, 3, 4, 5].reduce(combined, []);
console.log(result);

